/*-------------------Footer Img Slider------------------------*/
$( document ).ready(function() {

// When the user clicks on the button, scroll to the top of the document
function scrollTopFunction() {
  document.body.scrollTop = 0;
  document.documentElement.scrollTop = 0;
}
var href = window.location.href;
  if(href.indexOf('/content/mca/global/en/') > -1){
     $(".footerDisclaimer").hide();
  }
});



function viewMoreFunction() {
    document.getElementById("all_links").style.display = "block";
    document.getElementById("onload_mobileLinks").style.display = "none";
    document.getElementById("show_all").style.display = "none";        
}

// When the user clicks on the button, scroll to the top of the document
function scrollTopFunction() {
  document.body.scrollTop = 0;
  document.documentElement.scrollTop = 0;
}

/* New ScrollTop Changes */
let mcafoFooterMybutton = document.getElementById("btn-back-to-top");

// When the user scrolls down 20px from the top of the document, show the button
window.onscroll = function () {
  scrollNewFunction();
};

function scrollNewFunction() {
  if (
    document.body.scrollTop > 500 ||
    document.documentElement.scrollTop > 500
  ) {
    mcafoFooterMybutton.style.display = "block";
  } else {
    mcafoFooterMybutton.style.display = "none";
  }
}
